53	 */
54	
55	@RestController
56	@CrossOrigin(exposedHeaders = "errors, content-type")
57	@RequestMapping("/api")
58	public class OwnerRestControllerV1 implements OwnersApi {
59	
60	    /**
61	     * Syntactic email validation: a non-empty local part, a single '@', and a
62	     * domain with at least one dot-separated label ending in a letter-only TLD.
63	     */
64	    private static final Pattern EMAIL_PATTERN =
65	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(\\.[A-Za-z0-9-]+)*\\.[A-Za-z]{2,}$");
66	
67	    private final ClinicService clinicService;
68	
69	    private final OwnerMapper ownerMapper;
70	
71	    private final PetMapper petMapper;
72	
73	    private final VisitMapper visitMapper;
74	
75	    public OwnerRestControllerV1(ClinicService clinicService,
76	                                 OwnerMapper ownerMapper,
77	                                 PetMapper petMapper,
78	                                 VisitMapper visitMapper) {
79	        this.clinicService = clinicService;
80	        this.ownerMapper = ownerMapper;
81	        this.petMapper = petMapper;
82	        this.visitMapper = visitMapper;
83	    }
84	
85	    /**
86	     * Normalise a raw telephone number to E.164 form.
87	     *
88	     * <p>Spaces, dashes and brackets are stripped. A leading '+' and its country
89	     * code are kept when present; otherwise country code '+61' is assumed and a
90	     * single leading '0' is dropped from the national digits. The result must have
91	     * between 8 and 15 digits after the '+'.
92	     *
93	     * @return the E.164 string, or {@code null} if the input cannot form a valid one.
94	     */
95	    static String toE164(String raw) {
96	        if (raw == null) {
97	            return null;
98	        }
99	        String cleaned = raw.replaceAll("[\\s()\\[\\]-]", "");
100	        String digits;
101	        if (cleaned.startsWith("+")) {
102	            digits = cleaned.substring(1);
103	        } else {
104	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
105	            digits = "61" + national;
106	        }
107	        if (!digits.matches("[0-9]{8,15}")) {
108	            return null;
109	        }
110	        return "+" + digits;
111	    }
112	
113	    /**
114	     * Normalise a text field for case-insensitive, whitespace-insensitive identity
115	     * comparison: leading/trailing whitespace is trimmed, internal runs of whitespace
116	     * are collapsed to a single space, and the result is lower-cased. A {@code null}
117	     * input normalises to the empty string.
118	     */
119	    private static String normaliseIdentity(String value) {
120	        if (value == null) {
121	            return "";
122	        }
123	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
124	    }
125	
126	    /**
127	     * Normalise a postal address into its canonical stored form: leading/trailing whitespace is
128	     * trimmed, internal runs of whitespace are collapsed to a single space, the text is upper-cased,
129	     * and common street-type abbreviations are expanded ({@code ST -> STREET}, {@code RD -> ROAD},
130	     * {@code AVE -> AVENUE}). A {@code null} input normalises to the empty string. This is the value
131	     * that is both stored and used for every address comparison.
132	     */
133	    static String normaliseAddress(String value) {
134	        if (value == null) {
135	            return "";
136	        }
137	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase();
138	        if (collapsed.isEmpty()) {
139	            return "";
140	        }
141	        String[] tokens = collapsed.split(" ");
142	        StringBuilder result = new StringBuilder();
143	        for (int i = 0; i < tokens.length; i++) {
144	            if (i > 0) {
145	                result.append(' ');
146	            }
147	            result.append(expandAddressAbbreviation(tokens[i]));
148	        }
149	        return result.toString();
150	    }
151	
152	    /**
153	     * Expand a single upper-cased address token if it is a known street-type abbreviation, ignoring a
154	     * trailing period (so both {@code ST} and {@code ST.} become {@code STREET}). Unknown tokens are
155	     * returned unchanged.
156	     */
157	    private static String expandAddressAbbreviation(String token) {
158	        String core = token.endsWith(".") ? token.substring(0, token.length() - 1) : token;
159	        return switch (core) {
160	            case "ST" -> "STREET";
161	            case "RD" -> "ROAD";
162	            case "AVE" -> "AVENUE";
163	            default -> token;
164	        };
165	    }
166	
167	    /**
168	     * Build the customer code for a new owner as {@code '<LAST3>-<NNNN>'}, where LAST3 is the
169	     * upper-cased first three letters of the last name and NNNN is a global 4-digit zero-padded
170	     * sequence equal to one more than the current number of owners.
171	     */
172	    /**
173	     * Derive the stable, shared household identifier for owners sharing a household. It is a
174	     * deterministic UUID over the normalised last-name and address, so every owner in the same
175	     * household resolves to the same value regardless of the order in which they were created.
176	     */
177	    private static String householdId(String lastNameKey, String addressKey) {
178	        String seed = lastNameKey + "�" + addressKey;
179	        return UUID.nameUUIDFromBytes(seed.getBytes(StandardCharsets.UTF_8)).toString();
180	    }
181	
182	    private String nextCustomerCode(String lastName) {
183	        String letters = lastName == null ? "" : lastName;
184	        String last3 = letters.substring(0, Math.min(3, letters.length())).toUpperCase();
185	        int sequence = this.clinicService.findAllOwners().size() + 1;
186	        return String.format("%s-%04d", last3, sequence);
187	    }
188	
189	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
190	    @Override
191	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
192	        Collection<Owner> owners;
193	        if (lastName != null) {
194	            owners = this.clinicService.findOwnerByLastName(lastName);
195	        } else {
196	            owners = this.clinicService.findAllOwners();
197	        }
198	        if (owners.isEmpty()) {
199	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
200	        }
201	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
202	    }
203	
204	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
205	    @Override
206	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
207	        Owner owner = this.clinicService.findOwnerById(ownerId);
208	        if (owner == null) {
209	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
210	        }
211	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
212	    }
213	
214	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
215	    @Override
216	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
217	        String telephone = toE164(ownerFieldsDto.getTelephone());
218	        if (telephone == null) {
219	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
220	        }
221	        String email = ownerFieldsDto.getEmail();
222	        if (email != null && !EMAIL_PATTERN.matcher(email).matches()) {
223	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
224	        }
225	        String address = normaliseAddress(ownerFieldsDto.getAddress());
226	        if (address.isEmpty()) {
227	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
228	        }
229	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
230	            .map(Owner::getTelephone)
231	            .map(OwnerRestControllerV1::toE164)
232	            .filter(existing -> existing != null)
233	            .anyMatch(telephone::equals);
234	        if (telephoneInUse) {
235	            return new ResponseEntity<>(HttpStatus.CONFLICT);
236	        }
237	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
238	        String lastNameKey = normaliseIdentity(ownerFieldsDto.getLastName());
239	        String addressKey = address;
240	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
241	            .filter(existing ->
242	                normaliseIdentity(existing.getLastName()).equals(lastNameKey)
243	                    && normaliseAddress(existing.getAddress()).equals(addressKey))
244	            .toList();
245	        if (!householdMembers.isEmpty() && !sharesHousehold) {
246	            return new ResponseEntity<>(HttpStatus.CONFLICT);
247	        }
248	        HttpHeaders headers = new HttpHeaders();
249	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
250	        owner.setAddress(address);
251	        owner.setTelephone(telephone);
252	        owner.setEmail(email == null ? null : email.toLowerCase());
253	        if (owner.getRegistrationDate() == null) {
254	            owner.setRegistrationDate(LocalDate.now());
255	        }
256	        owner.setCustomerCode(nextCustomerCode(owner.getLastName()));
257	        if (sharesHousehold && !householdMembers.isEmpty()) {
258	            String householdId = householdId(lastNameKey, addressKey);
259	            owner.setHouseholdId(householdId);
260	            for (Owner member : householdMembers) {
261	                if (member.getHouseholdId() == null) {
262	                    member.setHouseholdId(householdId);
263	                    this.clinicService.saveOwner(member);
264	                }
265	            }
266	        }
267	        this.clinicService.saveOwner(owner);
268	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
269	        headers.setLocation(UriComponentsBuilder.newInstance()
270	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
271	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
272	    }
273	
274	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
275	    @Override
276	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
277	        String telephone = toE164(ownerFieldsDto.getTelephone());
278	        if (telephone == null) {
279	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
280	        }
281	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
282	        if (currentOwner == null) {
283	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
284	        }
285	        String email = ownerFieldsDto.getEmail();
286	        if (email != null && !EMAIL_PATTERN.matcher(email).matches()) {
287	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
288	        }
289	        currentOwner.setAddress(ownerFieldsDto.getAddress());
290	        currentOwner.setCity(ownerFieldsDto.getCity());
291	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
292	        currentOwner.setLastName(ownerFieldsDto.getLastName());
293	        currentOwner.setTelephone(telephone);
294	        currentOwner.setEmail(email == null ? null : email.toLowerCase());
295	        this.clinicService.saveOwner(currentOwner);
296	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
297	    }
298	
299	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
300	    @Transactional
301	    @Override
302	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
303	        Owner owner = this.clinicService.findOwnerById(ownerId);
304	        if (owner == null) {
305	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
306	        }
307	        this.clinicService.deleteOwner(owner);
308	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
309	    }
310	
311	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
312	    @Override
313	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
314	        Owner owner = this.clinicService.findOwnerById(ownerId);
315	        if (owner == null) {
316	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
317	        }
318	        HttpHeaders headers = new HttpHeaders();
319	        Pet pet = petMapper.toPet(petFieldsDto);
320	        owner.setId(ownerId);
321	        pet.setOwner(owner);
322	        pet.getType().setName(null);
323	        this.clinicService.savePet(pet);
324	        PetDto petDto = petMapper.toPetDto(pet);
325	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
326	            .buildAndExpand(pet.getId()).toUri());
327	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
328	    }
329	
330	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
331	    @Override
332	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
333	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
334	        if (currentOwner != null) {
335	            Pet currentPet = this.clinicService.findPetById(petId);
336	            if (currentPet != null) {
337	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
338	                currentPet.setName(petFieldsDto.getName());
339	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
340	                this.clinicService.savePet(currentPet);
341	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
342	            }
343	        }
344	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
345	    }
346	
347	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
348	    @Override
349	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
350	        HttpHeaders headers = new HttpHeaders();
351	        Visit visit = visitMapper.toVisit(visitFieldsDto);
352	        Pet pet = new Pet();
353	        pet.setId(petId);
354	        visit.setPet(pet);
355	        this.clinicService.saveVisit(visit);
356	        VisitDto visitDto = visitMapper.toVisitDto(visit);
357	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
358	            .buildAndExpand(visit.getId()).toUri());
359	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
360	    }
361	
362	
363	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
364	    @Override
365	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
366	        Owner owner = this.clinicService.findOwnerById(ownerId);
367	        if (owner != null) {
368	            Pet pet = owner.getPet(petId);
369	            if (pet != null) {
370	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
371	            }
372	        }
373	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
374	    }
375	}
